//! A sound module's functions (SINCE audiocodec 1.10): what
//! audiocodec.library calls a kind of sound's code in LIBS:codecs/ with
//! (sdk/libs/audiocodec/acodec.zig); the base is the module's, opened with
//! OpenLibrary("codecs/<kind>.acodec"). A stream is read and decoded by
//! whichever task has it, one at a time. A module answers ACERR_UNSUPPORTED
//! to a stream whose layout is not its own.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/acodec_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const acodec = @import("../libs/audiocodec/acodec.zig");
const media = @import("../libs/media/media.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "acodec";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const OpenACodec = libraries.lvo(4);
    pub const OpenACodecTrack = libraries.lvo(5);
    pub const CloseACodec = libraries.lvo(6);
    pub const DecodeACodec = libraries.lvo(7);
    pub const SeekACodec = libraries.lvo(8);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const OpenACodec = *const fn (*ACodecBase, *acodec.ACodecStream) callconv(.c) i32;
    pub const OpenACodecTrack = *const fn (*ACodecBase, *acodec.ACodecStream, *const media.MediaTrack) callconv(.c) i32;
    pub const CloseACodec = *const fn (*ACodecBase, *acodec.ACodecStream) callconv(.c) void;
    pub const DecodeACodec = *const fn (*ACodecBase, *acodec.ACodecStream, [*]i16, u32) callconv(.c) i32;
    pub const SeekACodec = *const fn (*ACodecBase, *acodec.ACodecStream, u32) callconv(.c) i32;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const ACodecBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *ACodecBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The stream's source read from where it is: its headers and tags, the
    /// info filled in, and the stream at its first sound: 0, or ACERR_* for
    /// bytes it cannot decode. On what opened the stream, which it reads.
    pub fn OpenACodec(self: *ACodecBase, stream: *acodec.ACodecStream) i32 {
        return libraries.call(self, LVO.OpenACodec, Fn.OpenACodec, .{stream});
    }

    /// A track of the stream's container: the codec's setup from `track`, the
    /// info filled in; packets come through `stream.media`. 0, or ACERR_*;
    /// ACERR_UNSUPPORTED from a kind no container carries. `track` is the
    /// caller's for the call alone.
    pub fn OpenACodecTrack(self: *ACodecBase, stream: *acodec.ACodecStream, track: *const media.MediaTrack) i32 {
        return libraries.call(self, LVO.OpenACodecTrack, Fn.OpenACodecTrack, .{ stream, track });
    }

    /// What the module holds of the stream given back, if it made anything:
    /// after a failed open too. The stream, its file and its tags stay the
    /// library's.
    pub fn CloseACodec(self: *ACodecBase, stream: *acodec.ACodecStream) void {
        return libraries.call(self, LVO.CloseACodec, Fn.CloseACodec, .{stream});
    }

    /// Up to `frames` frames of samples into `out`, the channels interleaved:
    /// how many, 0 at the end, ACERR_* below 0.
    pub fn DecodeACodec(self: *ACodecBase, stream: *acodec.ACodecStream, out: [*]i16, frames: u32) i32 {
        return libraries.call(self, LVO.DecodeACodec, Fn.DecodeACodec, .{ stream, out, frames });
    }

    /// The stream moved so that the next frame decoded is `frame`: 0, or
    /// ACERR_*. What it held decoded is dropped by the library.
    pub fn SeekACodec(self: *ACodecBase, stream: *acodec.ACodecStream, frame: u32) i32 {
        return libraries.call(self, LVO.SeekACodec, Fn.SeekACodec, .{ stream, frame });
    }
};
